Finally, we present the implementation details in MATLAB of our attempt to implement heteroscedastic GPs within the limited time we had, based on the most likely heteroscedastic Gaussian process method proposed by Kersting et al.


```
 gpcf = gpcf_sexp('lengthScale', 1, 'magnSigma2', 0.05, ...
                 'lengthScale_prior', pl, 'magnSigma2_prior', pm);
% Create the likelihood structure
lik = lik_huber('sigma2', 0.1^2, 'sigma2_prior', pn, 'weights', weights);

% ... Finally create the GP structure
gp_f = gp_set('lik', lik, 'cf', gpcf, 'jitterSigma2', 1e-9, ...
              'latent_method', 'MCMC', 'mode', 'homo');    % setting the mode as homoscedastic
gp_t = gp_set('lik', lik, 'cf', gpcf, 'jitterSigma2', 1e-9, ...
              'latent_method', 'MCMC');
gp_ft = gp_set('lik', lik, 'cf', gpcf, 'jitterSigma2', 1e-9, ...
               'latent_method', 'MCMC', 'mode', 'hetero'); % setting the mode as heteroscedastic

[f_gp, var_f] = fit_homoscedastic_gp(gp_f, x, y);
z = log(var_f);
% let us define z = log(sigma)

for iter = 1:max_iter
    %  (training f-process)
    [Ef0, Varf0] = gp_pred(f_gp, x, y);

    % (training t-process)
    z_gp = fit_homoscedastic_gp(gp_t, x, z);

    % 
    [z, ~] = gp_pred(z_gp, x, z, x);  % predict considering rr

    [ft_gp] = fit_heteroscedastic_gp(gp_ft, x, y);

    [Ef, Varf] = gp_pred_hetero(ft_gp, x, y, x, exp(z), exp(z));  % gp_pred_hetero(gp, input, output, test input, var_train, var_test)

    % Check for convergence
    [converged, values] = has_converged(Ef0, Varf0, Ef, Varf, tol);
    VAL(iter, :) = values;

    if converged
        break;
    else
        gp_f = gp_ft;
        gp_f.mode = 'homo';  % setting the mode as homoscedastic
        [f_gp, var_f] = fit_homoscedastic_gp(gp_f, x, y);
        z = log(var_f);
    end
end
```
